// ── Editorial content lookup (place descriptions / insider tips) ────────────
// Sidecar dictionaries keyed by place id; English fallback if missing.
// Ids may carry an 'imp_' prefix (food imports) — strip it before lookup.
import { PLACES_ZH } from '../data/i18n/places.zh.js'
import { TOPICS_ZH, DOMAINS_ZH, GROUPS_ZH, VENUES_ZH, FIGURES_ZH, WORKS_ZH } from '../data/i18n/content.zh.js'

function placeEntry(id) {
  if (_lang !== 'zh' || !id) return null
  return PLACES_ZH[String(id).replace(/^imp_/, '')] || null
}
// tDesc/tTip take the object AND the already-computed English fallback so
// call sites keep their own description || googleSummary || … chains intact.
// tDesc/tTip serve BOTH corpora: seed places (places.zh.js) and editorial
// venues (content.zh.js) — whichever dictionary knows the id wins.
export function tDesc(obj, en) {
  if (_lang !== 'zh') return en
  return placeEntry(obj?.id)?.d || VENUES_ZH[obj?.id]?.description || en
}
export function tTip(obj, en) {
  if (_lang !== 'zh') return en
  return placeEntry(obj?.id)?.t || VENUES_ZH[obj?.id]?.insiderTip || en
}

// Browse-by content: topics / domains / venue groups (groups keyed by English name).
export function tTopicF(id, field, en) { return (_lang === 'zh' && TOPICS_ZH[id]?.[field]) || en }
export function tDomainF(id, field, en) { return (_lang === 'zh' && DOMAINS_ZH[id]?.[field]) || en }
export function tGroupF(name, field, en) { return (_lang === 'zh' && GROUPS_ZH[name]?.[field]) || en }
export function tVenueF(id, field, en) { return (_lang === 'zh' && VENUES_ZH[id]?.[field]) || en }
export function tFigureF(id, field, en) { return (_lang === 'zh' && FIGURES_ZH[id]?.[field]) || en }
export function tWorkF(id, field, en) { return (_lang === 'zh' && WORKS_ZH[id]?.[field]) || en }

export function t(en) {
  if (_lang === 'en') return en
  return ZH[en] || en
}

// Parametrized variant: t2('Day {N}', { N: 3 }) → 第 3 天 / Day 3
export function t2(key, vars = {}) {
  let s = t(key)
  for (const [k, v] of Object.entries(vars)) s = s.split(`{${k}}`).join(String(v))
  return s
}
